:root {
  --paper: #fffdf8;
  --ink: #2f2735;
  --muted: #766d78;
  --line: #e8dfd7;
  --lavender: #eee8f7;
  --purple: #5f477b;
  --mint: #dcefe4;
  --mint-ink: #28704b;
}

.pour-card {
  width: 480px;
  padding: 16px;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
}

.wax-mark {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  font-size: 22px;
  background: var(--lavender);
  border-radius: 13px;
}

.title-group {
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h2 {
  margin: 0;
  font-size: 19px;
  line-height: 1.1;
}

.status {
  padding: 5px 9px;
  color: var(--mint-ink);
  font-size: 12px;
  font-weight: 700;
  background: var(--mint);
  border-radius: 999px;
}

.schedule {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 0;
  margin: 14px 0 10px;
  list-style: none;
}

.slot {
  padding: 10px;
  background: var(--lavender);
  border-radius: 10px;
}

.slot-label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 11px;
}

.slot strong {
  font-size: 14px;
}

.note {
  padding: 8px 10px;
  margin: 0;
  color: var(--purple);
  font-size: 13px;
  font-weight: 600;
  background: var(--paper);
  border: 1px dashed var(--line);
  border-radius: 8px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 12px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.actions {
  display: flex;
  gap: 7px;
}

button {
  padding: 7px 11px;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  border-radius: 8px;
}

.secondary {
  color: var(--purple);
  background: var(--paper);
  border: 1px solid var(--line);
}

.primary {
  color: var(--paper);
  background: var(--purple);
  border: 1px solid var(--purple);
}
